import json
from collections import deque

def handler(input_data):
    map_id = input_data["map_id"]
    start_x = int(input_data["start_x"])
    start_y = int(input_data["start_y"])
    target_x = int(input_data["target_x"])
    target_y = int(input_data["target_y"])
    travel_mode = input_data["travel_mode"]

    width, height = 30, 18
    grid = [[True for x in range(width)] for y in range(height)]

    # 1. Map Borders (solid rock boundaries)
    for x in range(width):
        grid[0][x] = False
        grid[height-1][x] = False
    for y in range(height):
        grid[y][0] = False
        grid[y][width-1] = False

    # 2. Blockages database
    if map_id == "0_228": # 1F Layout
        water_tiles = set()
        for y in [4, 5]:
            for x in range(14, 26): water_tiles.add((x, y))
        for y in [6, 7]:
            for x in range(8, 16): water_tiles.add((x, y))
        for y in range(6, 16):
            for x in [8, 9]: water_tiles.add((x, y))
        # Include missing water tiles at Columns 10 and 11, Rows 14 and 15
        for y in [14, 15]:
            for x in [10, 11]: water_tiles.add((x, y))

        # Water Ramps (can act as both or transition)
        ramps = {(23, 3), (15, 3), (11, 13), (25, 9)}

        # Solid Rock Obstacles on 1F
        rock_blockages = {
            (1, 17), (7, 6), (4, 1), (4, 2), (5, 3),
            (11, 8), (12, 8) # (11, 8) and (12, 8) are verified rock walls
        }
        # Central platform bounds and walls
        for x in range(15):
            rock_blockages.add((x, 3)) # Row 3 columns 0 to 14 are blocked on foot

        for y in range(height):
            for x in range(width):
                if (x, y) in rock_blockages:
                    grid[y][x] = False
                elif travel_mode == "foot":
                    # If walking on foot, treat all water tiles as impassable
                    if (x, y) in water_tiles and (x, y) not in ramps:
                        grid[y][x] = False
                elif travel_mode == "surf":
                    # If surfing, treat all non-water tiles as impassable
                    if (x, y) not in water_tiles and (x, y) not in ramps:
                        grid[y][x] = False

    elif map_id == "0_226": # 2F West Layout
        rock_blockages = {
            (3, 0), (9, 2), (9, 6), (13, 11), (13, 16), (16, 13),
            (1, 10), (1, 11), (1, 6), (2, 12), (2, 2), (2, 3), (2, 9), (2, 1),
            (3, 4), (4, 4), (4, 8), (5, 4), (5, 8), (6, 4), (6, 8), (7, 4), (7, 8), (8, 5), (8, 8),
            (9, 15), (9, 6)
        }
        # Multi-tile walls
        # Row 8 rock walls across Columns 3 to 12
        for x in range(3, 13): rock_blockages.add((x, 8))
        # Row 10 rock walls across Columns 13 to 20
        for x in range(13, 21): rock_blockages.add((x, 10))
        # Row 7 rock walls across Columns 13 to 17
        for x in range(13, 18): rock_blockages.add((x, 7))
        # Column 2 rock walls across Rows 1 to 13
        for y in range(1, 14): rock_blockages.add((2, y))
        # Row 4 rock walls across Columns 3 to 8
        for x in range(3, 9): rock_blockages.add((x, 4))
        # Row 6 rock walls across Columns 7 to 12
        for x in range(7, 13): rock_blockages.add((x, 6))

        for y in range(height):
            for x in range(width):
                if (x, y) in rock_blockages:
                    grid[y][x] = False

    # BFS Implementation
    start = (start_x, start_y)
    target = (target_x, target_y)

    if not (0 <= start_x < width and 0 <= start_y < height) or not grid[start_y][start_x]:
         return json.dumps({"error": "Start coordinate is out of bounds or blocked.", "start_passable": grid[start_y][start_x]})
    if not (0 <= target_x < width and 0 <= target_y < height) or not grid[target_y][target_x]:
         return json.dumps({"error": "Target coordinate is out of bounds or blocked.", "target_passable": grid[target_y][target_x]})

    queue = deque([[start]])
    visited = {start}
    path_found = None

    while queue:
        path = queue.popleft()
        cx, cy = path[-1]
        if (cx, cy) == target:
            path_found = path
            break
        for dx, dy in [(0, -1), (0, 1), (-1, 0), (1, 0)]:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < width and 0 <= ny < height and grid[ny][nx]:
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(path + [(nx, ny)])

    if path_found:
        dirs = []
        for i in range(len(path_found)-1):
            x1, y1 = path_found[i]
            x2, y2 = path_found[i+1]
            if x2 > x1: dirs.append('Right')
            elif x2 < x1: dirs.append('Left')
            elif y2 > y1: dirs.append('Down')
            elif y2 < y1: dirs.append('Up')
        return json.dumps({
            "path_found": True,
            "length": len(path_found),
            "coordinates": path_found,
            "directions": dirs
        })
    else:
        return json.dumps({"path_found": False, "message": "No path exists between the start and target coordinates."})
